(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sco"] = {"ui":{"skip":"Skip tae the content","back":"← Back tae AI-gile","lang.button":"Leid: {name}","lang.dialog":"Pick a leid","lang.search":"Seek leids","lang.none":"Nae leid matches","lang.notYet":"{name} isnae translatit yet","theme.aria":"Chynge theme: licht, dairk or black","theme.toLight":"Chynge tae the licht theme","theme.toDark":"Chynge tae the dairk theme","theme.toBlack":"Chynge tae the black theme (true black, easy on OLED screens)","words.underline":"Unnerline thir words on the page","words.underlineHelp":"Hover ower or tap a dottit word tae see whit it means.","index.title":"AI-gile: yer AI dev team, on the ae board","index.description":"AI-gile is a kanban board for AI codin teams. They wirk while ye sleep; ye get the ae wee pile o things tae decide, test an accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev team, on the ae&nbsp;board.","hero.alpha":"🐣 Steekit pre-alpha","hero.alphaTitle":"Early an unfinished: thanks for tryin it!","hero.lede":"They big while ye sleep. Ye wauken tae the ae wee pile: a few questions, a few things tae test, a purple diamond or twa. Clap, accept, an back tae yer coffee.","dl.windows":"Windows app","dl.browser":"Rin it in yer browser","dl.messenger":"📱 Messenger for yer phone","dl.soon":"Comin soon","dl.notify":"🔔 Tell me when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team niver needs a stand-up coffee. (They dae stand-ups onieweys.)","pitch.h2":"AI-gile in as mony words as ye like","pitch.lede":"Pick a length, frae the ae word tae 144. Ilka length is its ain description, scrievit for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 anither version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} caird on the board richt noo","count.line.html.other":"{n} cairds on the board richt noo","people.humans.html.one":"👥 {n} human","people.humans.html.other":"👥 {n} humans","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} at wark richt noo","people.working.html.other":"⚡ {n} at wark richt noo","pre.title":"AI-gile: somethin's bein biggit","pre.description":"Somethin's bein biggit here: a board whaur AI teams big whit ye ask for, an learn ye as they gang. Steekit pre-alpha wi pals for noo.","pre.h1":"Somethin's bein biggit here. 🤫","pre.line":"A board whaur AI teams big whit ye ask for, an learn ye as they gang. Steekit pre-alpha wi pals for noo.","pre.btn":"🔔 Tell me when it opens","pre.peek":"Ahint the gless: the real board, live. Ilka caird is a coloured baur.","pre.peekFake":"Ahint the gless: whit a board at wark looks like.","features.aria":"Whit it dis","f.pile.h":"The ae pile for ye","f.pile.html":"<b>For ye</b> haulds awthing waitin on ye, athort ilka project: questions, things tae test, jobs only a body can dae. Yer queue tells ye whit's neist an hou lang it taks.","f.sleep.h":"Teams that wirk while ye sleep","f.sleep.p":"Ilka project haes a lead an a team o AI agents. Comment on a caird an the team wakes up, daes the wirk, an hauns it back wi steps a tired body can follae.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore onything reaches ye, a tester follaes the steps in a copy o the app an shaws whit it saw, wi a screenshot. Flick thro the anes that passed an accept in a clap.","f.proof.h":"Proof, nae promises","f.proof.p":"Ilka haun-ower shaws whit chynged: the files, the diff, the screenshots. Nae openin ilka app tae see if it's duin.","f.chat.h":"Blether wi yer leads","f.chat.p":"A Discord-style rail: ae icon per project, purple diamonds for whit needs ye. Message a lead an idea; they turn it intae cairds an a plan, wi a ✅ Go button.","f.tidy.h":"Keeps itsel tidy","f.tidy.p":"Related cairds fauld intae ane, muddled titles get fixed, an a token check keeps the code lean. Fewer things tae flit atween, less tae think on.","f.private.h":"Yours, on yer computer","f.private.li1":"The board rins on yer ain machine an only answers tae ye.","f.private.li2":"Private DMs atween fowk are end-tae-end encryptit.","f.private.li3":"Nae accounts, nae trackers, nae cookies.","f.lang.h":"In yer ain leid","f.lang.p":"Ower 120 leids, frae Dutch, Welsh an Japanese tae pirate, Yoda an Klingon, wi a quick switch back tae English for the industry jargon.","f.service.h":"Fae an idea tae a real service","f.service.p":"Biggit somethin wi AI that fowk uise noo? Mark it as a service an the board helps ye rin it weel: uptime checks, a public status page, incidents wi a write-up, chynges that need a Go, backups checkit daily. Help learns ye ilka step as ye gang.","msgr.h2":"AI-gile Messenger: yer team in yer pooch","msgr.p1":"Blether wi yer AI team wioot openin the board. Chat wi yer project leads an yer pals, an see a caird's test steps an answer them, aw frae yer phone.","msgr.p2":"Tae pair it, scan a QR code on yer board. First time? A freendly demo chat shaws ye roond.","msgr.when":"Android first, syne a web version for phones an iPhone.","msgr.who":"Yer project lead","msgr.b1":"The dairk mode fix is ready. Want the test steps?","msgr.b2":"Aye, please!","msgr.b3":"1. Open Settins. 2. Pick Dairk. Dis it look richt?","tl.aria":"Timeline frae the first blether tae the roadmap","tl.h2":"Frae the first blether tae whit's neist","tl.lede":"Real dates an times, in yer ain time zone. Efter the day it's the plan, wi nae dates promised.","tl.today":"The day","tl.planned":"plannit","tl.cards.one":"{n} caird","tl.cards.other":"{n} cairds","join.h2":"Jyne in","join.lede":"AI-gile is bein biggit by a beardit weirdo wi AuDHD an a few mental health battles, an a hantle o patient agents. It's private for noo, in a steekit alpha wi freends. Fancy a shot when it opens up?","join.btn":"Register interest","join.small":"We'll email ye, naething else","footer.tag":"AI-gile. Nae trackers, nae cookies, nae stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"Whit we keep","footer.thanks":"Calls thanks tae ChilledChat","form.sending":"Sendin…","form.failed":"That didnae wirk: try again later.","form.offline":"Couldnae reach AI-gile: try again later.","form.keep":"We only use this tae reply tae ye, then delete it. Nae trackers, nae cookies.","form.keepLink":"Whit we keep","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email tae hear when AI-gile's steekit alpha or beta opens.","interest.h1":"🔔 Tell me when it opens","interest.lede":"AI-gile is in steekit pre-alpha. Leave yer email an we'll write the ae time, when there's a place for ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Steekit alpha: early, rouch, lots o chynges","interest.beta":"Beta: steadier, later","interest.both":"Either, whitever comes first","interest.submit":"Pit me on the list","interest.thanks":"Thanks! Ye're on the list.","licence.title":"AI-gile: business licence","licence.description":"Usin AI-gile in yer business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin AI-gile at wirk? Tell us wha ye are an whit ye dae. If it daes some guid, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"Whit ye dae","licence.how":"Hou it helps the warld","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Aw quiet","status.intro":"Is AI-gile wirkin richt noo? This page checks the website, board sharin, calls an the download every 5 minutes.","status.up":"Wirkin (answert in {ms} ms)","status.slow":"Didnae answer the last check, tryin again","status.down":"Doon: didnae answer the last twa checks","status.svc.web":"Website","status.svc.web.offers":"This site: whit AI-gile is, an the interest form","status.svc.boards":"Board sharin","status.svc.boards.offers":"Public boards, messages atween freends an invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video an screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer an invite links","status.checking":"Checkin…","status.offline":"Cannae reach the status service richt noo (tryin again)","status.updated":"updatit {ago}","status.justNow":"jist noo","status.min":"{n} min syne","status.hours":"{n} h syne","status.days":"{n} d syne","privacy.title":"AI-gile: whit we keep","privacy.h1":"Whit we keep","privacy.lede":"Short version: only whit ye send us, an no for lang.","privacy.only":"Only whit ye send us: whit ye type intae a form, like yer email. Naethin else aboot ye.","privacy.sealed":"It's sealt sae oor server cannae read it: in yer browser afore it leaves (on an aulder browser, the meenit it arrives). Only oor ain board can open it.","privacy.server":"It's deletit fae the server as soon as it reaches oor board. Onythin still there efter 30 days is deletit onywey.","privacy.board":"We keep it on oor board only till we've replied tae ye, then delete it there an aw.","privacy.none":"Nae trackers, nae cookies, nae analytics.","privacy.local":"Yer leid an yer licht or dark choice bide in yer ain browser. They're never sent tae us.","privacy.ask":"Want it gane sooner? Reply tae oor email an say sae.","live.h2":"Watch it bein biggit, live","live.caption":"Ilka caird is hid: ye see the shape o the wark, no the words.","live.watching.one":"live: {n} watchin","live.watching.other":"live: {n} watchin","live.last.now":"Last caird moved jist noo","live.last.min.one":"Last caird moved {n} min syne","live.last.min.other":"Last caird moved {n} min syne","live.last.hour.one":"Last caird moved {n} oor syne","live.last.hour.other":"Last caird moved {n} oors syne","live.last.day.one":"Last caird moved {n} day syne","live.last.day.other":"Last caird moved {n} days syne","live.offline":"The live board's takkin a wee breather. Come back suin.","live.cols":"Backlog|Tae dae|Gaun on|Team checkin|For ye tae test|For the team|Duin"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Haundit."]},{"n":2,"texts":["Robot kanban.","Agents, sortit.","Ideas, biggit."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["A kanban board rin by agents.","Ye write cairds. Agents big.","Free, local, tested, gey daft."]},{"n":8,"texts":["A free kanban board whaur AI agents wirk.","Write an idea. Agents big it. Ye accept.","Agile for the ae body an mony patient robots."]},{"n":13,"texts":["A kanban board on yer computer whaur AI agents tak up the cairds.","Write an idea. A team o agents bigs it. A tester checks it.","Free, nae accounts, nae trackers: a board, some robots, an ye in chairge."]},{"n":21,"texts":["AI-gile is a kanban board for wirkin wi AI codin agents. They tak up the cairds; ye test an accept them, an that's the lot.","Ilka project gets a lead an a team o AI agents. Comment on onie caird an the team gets stuck in tae the wirk.","A free, personal tae-dae board that rins on yer ain computer. The wirkers are robots. The ane that says aye is you."]},{"n":34,"texts":["Ye pit ideas on a board. A team o AI agents turns them intae wirkin features, tests them, an hauns them back wi steps tae try. Naething coonts as duin until ye say sae yersel.","AI-gile is a hamemade kanban board that Rich biggit wi a guid wheen o help frae the agents it noo manages. It's free, rins on yer computer, an is shared wi freends, nae sauld.","Picture an ordinar kanban board, wi columns frae Backlog tae Duin, except the cairds are ta'en up by AI agents. They report hou they're gettin on, ask questions when stuck, an aye wait on yer thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board whaur the team is made o AI agents. Ilka project haes a lead that plans the wirk an helpers that big it. When a feature is ready, an AI tester tries it oot an taks a screenshot, then it lands in yer pile. Accept it, or leave a comment an they rewirk it.","It started oot as ae body's wey o keepin track o lots o AI codin sessions at aince, an grew intae a richt board. It rins on yer machine, needs nae account, an haes nae trackers. It's free for freends an onybody that's curious. It's alsae unfinished, sae expect some rouch edges an the odd surprise.","Here's the honest version. Ye still hae tae hae the ideas, an ye still hae tae check the results. Whit AI-gile daes is awthing in atween: it keeps the cairds in order, wakes the richt agent when ye comment, shaws exactly whit chynged, an keeps the lot in the ae short pile for ye."]},{"n":89,"texts":["AI-gile is a free kanban board that ye rin on yer ain computer. Insteid o fowk, ilka project haes a team o AI agents: a lead that turns yer ideas intae cairds an a plan, an helpers that tak up the cairds in priority order. When somethin is biggit, an AI tester follaes the test steps an shaws ye whit it saw. Then it waits in the ae pile merked For ye. Ye accept it, or ye comment an the team haes anither go. Naething iver reaches Duin wioot ye.","A wheen o things ye micht nae expect. A nicht watch keeps the Tae dae column topped up while ye sleep, pickin cairds that dinnae need an answer frae ye. A token coonter shaws hou muckle the agents hae uised the day an this week, an Nae Token Mode tells them tae stop spendin. Ye can message freends, an private messages are end-tae-end encryptit. The board speaks aboot 120 leids, includin Dutch, Flemish, pirate an Klingon. Nane o it costs a penny, an naebody's tryin tae sell it tae ye either.","AI-gile is a wee personal project, nae a company. Rich wantit tae look efter several AI codin projects wioot openin ilka app tae check on them, sae he an the agents biggit a board for it, then uised the board tae big the rest o itsel. It's in steekit pre-alpha, which means it wirks, mair or less, for a haunfu o freends. There's nae pricin page, nae newsletter an nae growth plan. If it sounds uisefu, ye can ask tae try it when it opens up a wee bit mair."]},{"n":144,"texts":["AI-gile is a kanban board for the ae human an a guid wheen o AI agents. It rins on yer ain computer an it's completely free. Ye add projects, an ilka project gets a lead an a wee team. Ye blether wi the lead, a bit like Discord, an describe an idea; the lead turns it intae cairds an a plan, then waits for ye tae chap Go. The team wirks thro the cairds in priority order, uisin a simple command line made for leid models. Afore onything comes back tae ye, an AI tester follaes the steps in a copy o the app an attaches a screenshot. Finished wirk lands in yer pile wi the chynged files an the diff. Ye accept it, or ye leave a comment an the team wakes up an tries again. Only ye can muive a caird tae Duin.","A day wi AI-gile, mair or less. In the evenin ye leave a few comments: this button's in the wrang place, that list should be sortit, could we hae a dairk mode. Ye gang tae yer bed. The agents read the comments, mak the chynges, test them an hand them back tae ye. If Tae dae rins dry, the nicht watch fills it frae the backlog wi cairds that need nae answer frae ye. In the mornin there's the ae short pile: a couple o questions an a few things tae try, ilk wi steps a sleepy body can follae an a screenshot o it wirkin. Ye click thro, accept the guid anes an send back the rest. A token coonter shaws whit it aw uised, an Nae Token Mode is there for lean weeks. Then ye hae yer breakfast, which the agents canna help wi yet.","First, whit AI-gile isnae. It isnae a startup, it isnae for sale, an naebody's collectin yer data. It's a free board that rins on yer computer, wi nae accounts, nae trackers an nae cookies. Whit it is: the ae tidy place tae see ilka AI codin project at aince, wi a team o agents daein the cairds an you makin the decisions. It faulds related cairds thegither, fixes muddled titles, an keeps an ee on hou lean the code bides. It speaks aboot 120 leids, frae Dutch an Flemish tae pirate an Klingon. Freends can message ilk ither, privately an encryptit. It wis biggit by Rich an a guid wheen o patient agents, mostly uisin itsel. It's in steekit pre-alpha, sae it's rouch in places. If it sounds like fun, ask nicely an ye micht get in early."]}],"quips":{"1":"The ae word. Bold. Maybe ower bold.","3":"Three words. Awready mair honest than maist product pages.","8":"Echt words. Still shorter than a stand-up.","21":"The lengths are story points, by the wey. O course they are.","55":"Fifty-five words. Twa cairds got finished while ye read that.","144":"That's the lang ane. There's nae 233. The agents hae gaen tae bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The vera first blether, afore there wis ony code.","first-board.name":"First board","first-board.line":"A board that keeps track o its ain biggin: cairds, columns, drag an drap, projects.","team-roles.name":"Team an roles","team-roles.line":"Agent profiles, team templates, spaces an wha daes whit.","install.name":"Install an releases","install.line":"A zip a freend can install, self-updates, channels an rowin back.","usage-saver.name":"Usage saver","usage-saver.line":"Mizzer whit runs cost, keep the code lean, save yer limit.","friends.name":"Freends an sharin","friends.line":"Private DMs, a scrambled relay, invites, roles an shared projects.","languages.name":"Leids","languages.line":"Ilka screen text in a leid file, wi Dutch an Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks ilka haun-ower first an shaws whit it saw.","website.name":"The website","website.line":"aigile.lol, the teaser an this timeline.","streaming.name":"Chat an streamin","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs an emojis.","no-ai.name":"Nae AI edition","no-ai.line":"A board for fowk that code wioot AI, an public boards.","night-watch.name":"Nicht watch","night-watch.line":"A watchman an Scrum Master keep the teams on task while ye sleep.","p-more.name":"Awthing else","p-more.line":"Wee ideas still waitin their turn.","p-android.name":"Phone an Android","p-android.line":"Reach yer board frae a phone, then a native Android app.","p-release.name":"Alpha an ayont","p-release.line":"Steekit alpha, the live site, then beta.","p-languages.name":"Mair leids","p-languages.line":"Mair than a hunner leids, an an immersion mode for learners.","p-engines.name":"Mair AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cairds an guard rails.","p-self.name":"Lookin efter ye","p-self.line":"Tired mode, self-care reminders an 4:20.","p-servers.name":"Servers an scale","p-servers.line":"Global server settings, roles an plannin for growth.","p-livestream.name":"Streamin extras","p-livestream.line":"Twitch chat, custom emojis an a public live view."},"words":{"button":"📖 Industry jargon","h":"📖 Wirds explained","intro":"The wirds ye meet in AI-gile, in plain speak: biggin it, chyngin it safe, keepin it rinnin fer the fowk that uise it, an warkin as a team wi AI.","search":"Seirch a word…","none":"Nae word matches that.","close":"Close","count":{"one":"{count} wird","other":"{count} wirds"},"groups":[{"id":"build","name":"🛠️ Biggin it"},{"id":"change","name":"🔀 Chyngin it safe"},{"id":"run","name":"🛎️ Rinnin a service"},{"id":"team","name":"🤝 Warkin as a team (an wi AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"The project's folder o code an its full history o commits, usually aye kept on GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line o wark in the code, sae chynges can be made wioot touchin the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot o the code, wi a short note o whit chynged. Ye can aye gang back tae ane.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sendin saved snapshots (commits) frae this computer up tae GitHub, sae they're backit up an shared."},{"id":"merge","g":"build","word":"Merge","text":"Jinin a branch's chynges back intae the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Askin for a branch's chynges tae be checked an merged intae the main version.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidyin the code wioot chyngin whit it dis: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Somethin that disnae wark the wey it should.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Tryin a feenished piece o wark tae check it dis whit wis askit, afore ye accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short fer quality assurance: the automatic checks that rin afore onythin gaes live. When QA is red, somethin failed, an it cannae gang live till that's fixed.","also":["quality checks","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pittin a new version live, for example ontae a server whaur fowk uise it."},{"id":"release","g":"change","word":"Release","text":"A named bundle o feenished wark that gaes live thegither, wi short notes on whit chynged. 🚀 Releases writes the notes fae the duin cairds.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Gaun back tae the last version that wirked when a new ane causes bother. In AI-gile it maks a checklist o the undae steps written on ilka chynge.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that fowk uise, no a copy fer tryin things oot. Developers cry it production an aw.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Chynge","text":"A planned chynge tae somethin fowk rely on, written doon first: whit, how come, the risk, when, an how tae undae it. Stert ane wi 🔀 Raise a chynge.","also":["change","chynges","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Somethin that could gang wrang, scored on how likely an how bad it wid be. ⚠️ Risks keeps them in ae list, heichest score first, ilk ane wi a date tae look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Chynge windae","text":"The times when chynges may gang live, like a quiet Tuesday nicht. Ootside a windae a chynge caird cannae be feenished, unless it's an emergency.","also":["chynge windaes","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote jist afore a chynge gaes live: ilka body that has tae approve says Go or No go. It only gaes aheid when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waitin on an aye afore wark sterts. A caird a pal raises, or a chynge, waits in ✅ Approvals till ye approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch o time, like a stream, a demo or the nicht, when nocht gaes live. The teams keep warkin an testin, but gaun live bides till it ends. Ither places cry it a chynge freeze.","also":["quiet times","chynge freeze","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Somethin ye biggit that fowk rely on, like a website or an app, lookit efter sae it keeps wirkin. Tick “This project is a service” an say whit it offers, wha uises it an wha's on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, ilka few minutes, that yer service still answers. If it fails a wheen o times in a row, AI-gile opens an incident caird by itsel.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is wirkin (green, orange or red) wi the latest update, sae the fowk that uise it can check insteid o speirin.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Somethin that's broke fer the fowk uisin it richt noo, like the website bein doon. A 🔥 incident caird jumps the queue: gettin it wirkin again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A muckle incident: lots o fowk hit, or siller or data at risk. Ae button pits ilka team on it (swarm), wauks whaever's on call an asks fer a status update ilka 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Bein the ane that answers when somethin breks, even at nicht. Ilka service has an on-call team member that's waukit first fer its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How lang a caird may wait fer a first answer, for example an oor fer an incident. Efter that it gets a red clock, sae nocht is quietly forgot. Cried a response target an aw.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back efter an incident: whit happened, whit helped an whit tae chynge, wi'oot blamin onybody. An incident cannae be closed wi'oot ane.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause ahint ane or mair incidents. A 🧩 problem caird gethers incidents that keep comin back, sae the cause is fund an fixed fer guid.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason somethin broke, no jist whit ye saw gaun wrang. Fix the root cause an the incident stops comin back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A wey tae keep things wirkin till the real fix is ready, like restertin somethin when it gets stuck. It's written on the problem caird sae naebody has tae wark it oot again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whase cause is unnerstood an that has a workaround, but isnae fixed yet. 🧩 Known errors lists them, sae awbody uises the workaround insteid o howkin again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions fer fixin a kent kind o bother, sae it's duin the same wey, quick, ilka time. Efter a muckle incident the team can propose ane fer ye tae OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy o yer data fae afore, tae faw back on if somethin's lost or damaged. AI-gile maks a backup o yer boards ilka day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Pittin data back fae a backup. A backup only really coonts aince ye ken it can be restored, sae it's worth tryin noo an again.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideas an wark no plannit in yet. Nocht there gets warked on till it muives tae To do."},{"id":"sprint","g":"team","word":"Sprint","text":"A short stretch o wark (aften a week or twa) wi an agreed set o cairds tae feenish.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"A quick check-in: whit ilka team member did, whit they dae next, an whit's stoppin them.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"A board wi columns (To do, In progress, Done) whaur cairds muive left tae richt as wark happens."},{"id":"wip","g":"team","word":"WIP limit","text":"Wark in progress: the maist cairds a column should haud, sae the team feenishes things afore stertin mair.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition o Duin","text":"The team's short checklist o whit “feenished” means, like testit an explained, afore a caird is haundit tae ye. Its twin, the Definition o Ready, says when a caird is clear eneuch tae stert.","also":["Definition of Done","Definition of Ready","Definition o Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The feenished cairds waitin fer ye tae try, ane efter anither. Accept ane or send it back wi a note, an the next ane comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team warks, tae agree on ae thing tae dae better. In AI-gile a retro suggests a chynge tae the team's weys o warkin, an ye say Go or No yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair o een: anither AI checks ilka caird's wark afore it reaches ye, sae fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Aw haunds on deck: ilka team draps ither wark tae help on ae urgent project till it's sortit. Ither projects wait in the meantime.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The ane that keeps the wark flowin: spots stuck cairds, nudges the teams an minds ye o whit's waitin. In AI-gile the Lead Scrum Master daes this ower ilka project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"An AI that warks on its ain on a task: reads the code, maks chynges, rins checks, an reports back.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"The unit AI usage is coontit in: roughly a few letters o text read or written. Fewer tokens, mair o yer plan left.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"A wee command that rins by itsel at a set moment, e.g. whan an AI session sterts, sae the team hears yer comments.","also":["hooks"]}]}};
